'use strict';
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let paused=motionQuery.matches;motionQuery.addEventListener('change',e=>{paused=e.matches;});
const services=['SEO','Web Development','Landing Page'];const cart=new Set();try{const saved=JSON.parse(localStorage.getItem('rizwan-services')||'[]');if(Array.isArray(saved))saved.filter(x=>services.includes(x)).forEach(x=>cart.add(x));}catch{}
const dialog=document.querySelector('#cart-dialog');const items=document.querySelector('#cart-items');let lastFocus;function closeCart(){dialog.close();document.body.style.overflow='';lastFocus?.focus();}function openCart(){lastFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';}document.querySelectorAll('[data-open-cart]').forEach(b=>b.addEventListener('click',openCart));document.querySelector('#close-cart').addEventListener('click',closeCart);dialog.addEventListener('cancel',e=>{e.preventDefault();closeCart();});dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)closeCart();});
function renderCart(){try{localStorage.setItem('rizwan-services',JSON.stringify([...cart]));}catch{}document.querySelectorAll('[data-count]').forEach(n=>n.textContent=cart.size);items.replaceChildren();if(!cart.size){const p=document.createElement('p');p.className='empty-cart';p.textContent='Your brief is empty. Choose website development, a landing page or SEO to get started.';items.append(p);const b=document.createElement('button');b.className='pill dark';b.textContent='Choose services';b.onclick=()=>{closeCart();document.querySelector('#services').scrollIntoView({behavior:paused?'instant':'smooth'});};items.append(b);}for(const service of cart){const row=document.createElement('div');row.className='cart-item';const name=document.createElement('strong');name.textContent=service;const remove=document.createElement('button');remove.textContent='Remove';remove.setAttribute('aria-label',`Remove ${service}`);remove.onclick=()=>{cart.delete(service);renderCart();};row.append(name,remove);items.append(row);}document.querySelector('#checkout').disabled=!cart.size;document.querySelectorAll('[data-service-choice]').forEach(input=>{input.checked=cart.has(input.dataset.serviceChoice);});document.querySelectorAll('[data-service]').forEach(b=>{const selected=cart.has(b.dataset.service);b.innerHTML=selected?'Added to brief <span>✓</span>':'Add to brief <span>+</span>';b.setAttribute('aria-pressed',String(selected));});}
let toastTimer;document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{if(cart.has(b.dataset.service)){openCart();return;}cart.add(b.dataset.service);renderCart();const toast=document.querySelector('#toast');toast.textContent=`${b.dataset.service} added — open “Your brief” to checkout.`;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3500);}));renderCart();
function buildWhatsAppUrl(selected,name,website,brief){const message=['Hello Rizwan, I would like to request the following services:',...selected.map(s=>`• ${s}`),name?`\nName: ${name}`:'',website?`Website: ${website}`:'',brief?`\nProject brief: ${brief}`:'','\nPlease let me know the next steps and a quote.'].filter(Boolean).join('\n');return 'https://wa.me/447404303928?text='+encodeURIComponent(message);}
document.querySelector('#checkout-form').addEventListener('submit',e=>{e.preventDefault();if(!cart.size)return;const data=new FormData(e.currentTarget);const url=buildWhatsAppUrl([...cart],data.get('name').trim(),data.get('website').trim(),data.get('brief').trim());window.open(url,'_blank','noopener,noreferrer');});
// Service selection is shared with the order drawer.
document.querySelectorAll('[data-service-choice]').forEach(input=>input.addEventListener('change',()=>{if(input.checked)cart.add(input.dataset.serviceChoice);else cart.delete(input.dataset.serviceChoice);renderCart();}));
document.querySelector('#year').textContent=new Date().getFullYear();
const menuToggle=document.querySelector('.menu-toggle'),mainMenu=document.querySelector('#main-menu');function closeMenu(){menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Open navigation');mainMenu.classList.remove('open');}menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');mainMenu.classList.toggle('open',open);});mainMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu();});
// One-time entrance animation. No permanently hidden content or scroll hijacking.
const entrance=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){if(!paused)entry.target.classList.add('entering');entrance.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>entrance.observe(el));
const hero=document.querySelector('.hero'),portrait=document.querySelector('.hero-portrait'),heading=document.querySelector('.hero-heading'),columns=[...document.querySelectorAll('.project-column')],work=document.querySelector('.work');let queued=false;const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));function motionFrame(){queued=false;const small=innerWidth<=700;const hr=hero.getBoundingClientRect();const y=clamp(-hr.top,0,hero.offsetHeight);portrait.style.translate=paused||small?'none':`0 ${y*.13}px`;heading.style.translate=paused||small?'none':`0 ${y*.055}px`;const wr=work.getBoundingClientRect();const progress=clamp((innerHeight-wr.top)/(innerHeight+wr.height),0,1);columns.forEach((column,i)=>column.style.translate=paused||small?'none':`0 ${(progress-.5)*(i?90:-60)}px`);}function queueMotion(){if(!queued){queued=true;requestAnimationFrame(motionFrame);}}addEventListener('scroll',queueMotion,{passive:true});addEventListener('resize',queueMotion);motionQuery.addEventListener('change',queueMotion);queueMotion();
